// A book's text, read once its file is there, in parts the home's main bot summarises one by one into each part's
// summary (the rule part_heading takes the heading off its first line).
const MAX_PARTS = 80;
const PART_MAX = 7000;
const PART_MIN = 2500;
const TASK = "This is one part of a book someone uploaded so they can learn from it. Answer with a first line that starts with \"# \" and gives this part a short, clear heading (at most 8 words), then 2 to 4 friendly sentences on what this part teaches. Write in the language of the book. No other text.";

function partsOf(whole) {
  const text = String(whole || "").replace(/\r\n?/g, "\n").replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
  const usable = text.slice(0, MAX_PARTS * PART_MAX);
  const size = Math.min(PART_MAX, Math.max(PART_MIN, Math.ceil(usable.length / MAX_PARTS)));
  const parts = [];
  let start = 0;
  while (start < usable.length && parts.length < MAX_PARTS) {
    let end = Math.min(usable.length, start + size);
    if (end < usable.length) {
      const floor = start + Math.floor(size * 0.6);
      const paragraph = usable.lastIndexOf("\n\n", end);
      const line = usable.lastIndexOf("\n", end);
      const sentence = usable.lastIndexOf(". ", end);
      if (paragraph > floor) end = paragraph + 2;
      else if (line > floor) end = line + 1;
      else if (sentence > floor) end = sentence + 2;
    }
    const part = usable.slice(start, end).trim();
    if (part) parts.push(part);
    start = end;
  }
  return { parts, cut: text.length > usable.length || start < usable.length };
}

async function main(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  for (const id of ids) {
    const book = await records.get("books", id);
    if (!book || !book.file) continue;
    let read;
    try {
      read = await docs.text({ record: { table: "books", id }, field: "file" });
    } catch (error) {
      await records.update("books", id, { contents_status: "Problem", contents_note: "I couldn't read this file: " + String((error && error.message) || error).slice(0, 240) });
      return { read: id, parts: 0 };
    }
    const { parts, cut } = partsOf(read.text);
    if (!parts.length) {
      await records.update("books", id, { contents_status: "Problem", contents_note: "This file has no text I can read. A scanned book needs its text first: try a text, Word or PDF file with words in it." });
      return { read: id, parts: 0 };
    }
    const earlier = await records.list("book_parts", { where: "=book == params.book", params: { book: id }, limit: 100 });
    for (const part of earlier) await records.markObsolete("book_parts", part.id);
    const about = "the book \"" + (book.title || "Untitled") + "\"" + (book.author ? " by " + book.author : "");
    const items = [];
    for (let index = 0; index < parts.length; index += 1) {
      const made = await records.create("book_parts", { book: id, position: index + 1, text: parts[index] });
      items.push({ record: { table: "book_parts", id: made.id }, text: "Part " + (index + 1) + " of " + parts.length + " of " + about + ":\n" + parts[index] });
    }
    await records.update("books", id, {
      contents_status: "Reading",
      contents_note: read.more || cut ? "It's a long one: I read the first " + parts.length + " parts, about " + Math.round(parts.join("").length / 2000) + " pages." : ""
    });
    await ai.work({ bot: "default", task: TASK, items, into: "summary" });
    return { read: id, parts: parts.length };
  }
  return { read: null, parts: 0 };
}

// The bot answers a part with "# <heading>" on its first line, then the summary: the heading goes in its own field.
function main(input) {
  const text = String((input.record && input.record.summary) || "");
  const found = /^\s*#+\s*(.+?)\s*(?:\n|$)/.exec(text);
  if (!found) return {};
  return { set: { heading: found[1].replace(/[*_`]/g, "").trim().slice(0, 120), summary: text.slice(found[0].length).trim() } };
}

// A course to plan (its status set to Planning: a new one, or Plan again): the home's main bot plans it from what the
// person wants to learn, their level, what to change, the course so far and the book's parts, into its plan; a cover
// is drawn for a course without one.
const ROOM = 7900;
const TASK = "Plan a complete, fun course that teaches the person what they want to learn, at their level, step by step from easy to harder. When a book is given, build the course on its parts. Answer only in this format, one item a line, no other text:\nCOURSE: <one emoji> <a short, catchy course title>\nUNIT: <one emoji> <unit title> | <one line on what the unit covers>\nLESSON: <one emoji> <lesson title> | <one line on what they will learn> | <the numbers of the book parts it uses, such as 3, 4; blank without a book>\nGive 3 to 6 units, each with 2 to 5 lessons, at most 30 lessons in all; every LESSON line belongs to the UNIT line above it. Keep every line short. If the course so far is given, change it only as asked and keep the exact titles of the lessons that stay.";

const firstSentence = (text) => String(text || "").split(/(?<=[.!?])\s/)[0].slice(0, 160);

function planText(course, book, parts, units, lessons) {
  const lines = ["What I want to learn: " + course.goal];
  if (course.level) lines.push("How much I know already: " + course.level);
  if (course.changes) lines.push("What to change this time: " + course.changes);
  if (lessons.length) {
    lines.push("The course so far (keep the exact titles of the lessons that stay):");
    for (const unit of units) {
      lines.push("UNIT: " + unit.title + " | " + (unit.about || ""));
      for (const lesson of lessons.filter((entry) => entry.unit === unit.id)) lines.push("LESSON: " + lesson.title + " | " + (lesson.goal || "") + " | " + (lesson.parts || ""));
    }
  }
  let text = lines.join("\n");
  if (book && parts.length) {
    text += "\nThe book \"" + book.title + "\"" + (book.author ? " by " + book.author : "") + ", part by part:";
    const full = parts.map((part) => part.position + ". " + (part.heading || "") + " - " + (firstSentence(part.summary) || String(part.text || "").slice(0, 120).replace(/\s+/g, " ")));
    const short = parts.map((part) => part.position + ". " + (part.heading || String(part.text || "").slice(0, 60).replace(/\s+/g, " ")));
    const contents = full.join("\n").length + text.length < ROOM ? full : short;
    for (const line of contents) {
      if (text.length + line.length + 1 > ROOM) break;
      text += "\n" + line;
    }
  }
  return text.slice(0, ROOM);
}

async function main(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  for (const id of ids) {
    const course = await records.get("study_courses", id);
    if (!course || course.status !== "Planning") continue;
    const book = course.book ? await records.get("books", course.book) : null;
    const parts = book ? await records.list("book_parts", { where: "=book == params.book", params: { book: book.id }, sort: "position", limit: 100 }) : [];
    const units = await records.list("study_units", { where: "=course == params.course", params: { course: id }, sort: "position", limit: 100 });
    const lessons = await records.list("study_lessons", { where: "=course == params.course && status != \"Put away\"", params: { course: id }, sort: "position", limit: 100 });
    await records.update("study_courses", id, { plan: "", note: "" });
    await ai.work({ bot: "default", task: TASK, items: [{ record: { table: "study_courses", id }, text: planText(course, book, parts, units, lessons) }], into: "plan" });
    if (!course.cover) {
      await ai.picture({
        prompt: "A bright, cheerful flat illustration for a course cover, bold simple shapes and happy colours, no words or letters. The course is about: " + String(course.goal).slice(0, 300),
        into: { table: "study_courses", id, field: "cover" }
      });
    }
    return { planning: id };
  }
  return { planning: null };
}

// The bot's plan made into the course's units and lessons. The forgiving rule for a changed plan: a unit or lesson
// whose title stays the same (emoji, case and punctuation aside) is kept, with its lessons' text, quiz and progress,
// moved to its new place; a new one is made (a lesson to be written, so it shows as new); one the plan leaves out is
// put away (marked obsolete).
const keyOf = (title) => String(title || "").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim();

function parsePlan(text) {
  const plan = { title: "", units: [] };
  for (const raw of String(text || "").split("\n")) {
    const line = raw.replace(/^[\s*#>-]+/, "").replace(/\*\*/g, "").trim();
    const found = /^(COURSE|UNIT|LESSON)\s*:\s*(.+)$/i.exec(line);
    if (!found) continue;
    const [title = "", second = "", third = ""] = found[2].split("|").map((part) => part.trim());
    const kind = found[1].toUpperCase();
    if (kind === "COURSE") plan.title = title.slice(0, 200);
    else if (kind === "UNIT" && title) plan.units.push({ title: title.slice(0, 200), about: second.slice(0, 300), lessons: [] });
    else if (kind === "LESSON" && title && plan.units.length) {
      plan.units[plan.units.length - 1].lessons.push({ title: title.slice(0, 200), goal: second.slice(0, 300), parts: third.replace(/[^0-9,\s]/g, "").replace(/\s+/g, " ").trim().slice(0, 60) });
    }
  }
  plan.units = plan.units.filter((unit) => unit.lessons.length).slice(0, 8);
  return plan;
}

/** The first record of `left` (a Map of key to records) with this title's key, taken out of it. */
function take(left, title) {
  const found = left.get(keyOf(title));
  if (!found || !found.length) return null;
  return found.shift();
}

const byKey = (rows) => {
  const map = new Map();
  for (const row of rows) map.set(keyOf(row.title), [...(map.get(keyOf(row.title)) || []), row]);
  return map;
};

async function main(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  const built = [];
  for (const id of ids) {
    const course = await records.get("study_courses", id);
    if (!course || !course.plan) continue;
    const plan = parsePlan(course.plan);
    if (!plan.units.length) {
      await records.update("study_courses", id, { status: "Problem", note: "The plan came back in a shape I can't use. Press Plan again." });
      continue;
    }
    const units = byKey(await records.list("study_units", { where: "=course == params.course", params: { course: id }, sort: "position", limit: 100 }));
    const lessons = byKey(await records.list("study_lessons", { where: "=course == params.course && status != \"Put away\"", params: { course: id }, sort: "position", limit: 100 }));
    let writing = 0;
    let kept = 0;
    let putAway = 0;
    // Lessons it keeps that are still being written (a plan redone meanwhile, or another run's): the course isn't ready.
    let stillWriting = 0;
    for (let place = 0; place < plan.units.length; place += 1) {
      const spec = plan.units[place];
      const position = place + 1;
      let unit = take(units, spec.title);
      if (!unit) unit = await records.create("study_units", { course: id, title: spec.title, about: spec.about, position });
      else if (unit.position !== position) await records.update("study_units", unit.id, { position });
      for (let step = 0; step < spec.lessons.length; step += 1) {
        const wanted = spec.lessons[step];
        const at = position * 100 + step + 1;
        const same = take(lessons, wanted.title);
        if (!same) {
          await records.create("study_lessons", { course: id, unit: unit.id, position: at, title: wanted.title, goal: wanted.goal, parts: wanted.parts, status: "Writing" });
          writing += 1;
          continue;
        }
        kept += 1;
        if (same.status === "Writing") stillWriting += 1;
        if (same.unit !== unit.id || same.position !== at) await records.update("study_lessons", same.id, { unit: unit.id, position: at });
      }
    }
    for (const rows of units.values()) for (const row of rows) await records.markObsolete("study_units", row.id);
    const leftOut = [...lessons.values()].flat();
    if (leftOut.length) {
      // Everyone's progress in a lesson left out goes with it (each person's own: a job reaches them all).
      const gone = new Set(leftOut.map((row) => row.id));
      for (const row of await records.list("study_progress", { where: "=course == params.course", params: { course: id }, limit: 100 })) {
        if (gone.has(row.lesson)) await records.markObsolete("study_progress", row.id);
      }
    }
    for (const row of leftOut) {
      await records.markObsolete("study_lessons", row.id);
      putAway += 1;
    }
    // How many lessons this round writes, and when it started: the course page's count and rough time left.
    const toWrite = writing + stillWriting;
    const round = toWrite ? { to_write: toWrite, ...(writing ? { writing_started: new Date().toISOString() } : {}) } : {};
    const status = toWrite ? "Writing" : "Ready";
    await records.update("study_courses", id, { title: plan.title || course.title || course.goal.slice(0, 80), status, changes: "", note: "", ...round });
    built.push({ course: id, units: plan.units.length, writing, kept, putAway, status });
  }
  return { built };
}

// Lessons to write (new ones, and ones someone asked to rewrite): the home's main bot writes each, with its quiz, from
// the course, its unit and the book parts it uses, into the lesson's material; make_quiz takes them from there.
const ROOM = 7900;
const TASK = "Write one short, fun lesson of a course for the person learning it, and a quiz on it. Build it on the book's text when it is given. Answer only in this format.\nFirst the lesson: 3 to 6 short paragraphs, at most 350 words, friendly and clear, with one example from everyday life. Plain text: no headings, lists or markdown.\nThen a line with only the word QUIZ, then 4 questions, each exactly like this:\nQ: <the question>\nA: <a choice>\nB: <a choice>\nC: <a choice>\nD: <a choice>\nANSWER: <the letter of the right choice>\nWHY: <one short sentence on why>\nOnly one choice is right; vary which letter it is. Write in the language of the course.";

function lessonText(course, unit, lesson, parts) {
  const lines = [
    "The course: " + (course.title || course.goal) + ", for someone who wants to learn: " + course.goal + (course.level ? " (" + course.level + ")" : ""),
    "Unit: " + (unit ? unit.title + (unit.about ? " - " + unit.about : "") : ""),
    "This lesson: " + lesson.title,
    "They will learn: " + (lesson.goal || lesson.title)
  ];
  if (lesson.request) lines.push("Change this time: " + lesson.request);
  let text = lines.join("\n");
  const wanted = String(lesson.parts || "").split(/[^0-9]+/).filter(Boolean).map(Number);
  const used = parts.filter((part) => wanted.includes(Number(part.position)));
  if (used.length) {
    text += "\nFrom the book, part" + (used.length > 1 ? "s " : " ") + used.map((part) => part.position).join(", ") + ":";
    for (const part of used) {
      const room = ROOM - text.length - 1;
      if (room < 200) break;
      text += "\n" + String(part.text || part.summary || "").slice(0, room);
    }
  }
  return text.slice(0, ROOM);
}

async function main(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  const courses = {};
  const units = {};
  const books = {};
  const items = [];
  for (const id of ids) {
    const lesson = await records.get("study_lessons", id);
    if (!lesson || lesson.status !== "Writing") continue;
    if (!(lesson.course in courses)) courses[lesson.course] = await records.get("study_courses", lesson.course);
    const course = courses[lesson.course];
    if (!course) continue;
    if (lesson.unit && !(lesson.unit in units)) units[lesson.unit] = await records.get("study_units", lesson.unit);
    if (course.book && !(course.book in books)) {
      books[course.book] = await records.list("book_parts", { where: "=book == params.book", params: { book: course.book }, sort: "position", limit: 100 });
    }
    items.push({ record: { table: "study_lessons", id }, text: lessonText(course, units[lesson.unit], lesson, books[course.book] || []) });
  }
  if (items.length) await ai.work({ bot: "default", task: TASK, items, into: "material" });
  return { writing: items.length };
}

// A lesson the bot has written: its text goes on the lesson and its quiz becomes the lesson's questions (an earlier
// quiz is put away, so a rewritten lesson starts fresh, as new). A course whose lessons are all written is ready.
const PER_RUN = 8;

function parseLesson(material) {
  const lines = String(material || "").replace(/\r/g, "").split("\n");
  const at = lines.findIndex((line) => /^[\s*#]*QUIZ\b/i.test(line));
  const text = (at < 0 ? lines : lines.slice(0, at)).join("\n").replace(/\n{3,}/g, "\n\n").trim();
  const questions = [];
  let question = null;
  for (const raw of at < 0 ? [] : lines.slice(at + 1)) {
    const line = raw.replace(/^[\s*#>-]+/, "").replace(/\*\*/g, "").trim();
    let found;
    if ((found = /^Q(?:uestion)?\s*\d*\s*[:.)]\s*(.+)$/i.exec(line))) {
      question = { question: found[1], choices: {}, answer: "", why: "" };
      questions.push(question);
    } else if (!question) {
      continue;
    } else if ((found = /^ANSWER\s*[:.)-]?\s*\(?([ABCD])\b/i.exec(line))) {
      question.answer = found[1].toUpperCase();
    } else if ((found = /^WHY\s*[:.)-]?\s*(.+)$/i.exec(line))) {
      question.why = found[1];
    } else if ((found = /^\(?([ABCD])\s*[:.)]\s*(.+)$/i.exec(line))) {
      question.choices[found[1].toUpperCase()] = found[2];
    }
  }
  const whole = questions.filter((entry) => entry.question && entry.answer && ["A", "B", "C", "D"].every((letter) => entry.choices[letter]));
  return { text, questions: whole.slice(0, 6) };
}

async function main(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  // Any lesson written while this job wasn't told (a run that failed), so none waits for ever.
  for (const lesson of await records.list("study_lessons", { where: "=status == \"Writing\" && material != \"\"", limit: PER_RUN })) {
    if (!ids.includes(lesson.id)) ids.push(lesson.id);
  }
  const courses = [];
  let written = 0;
  for (const id of ids.slice(0, PER_RUN)) {
    const lesson = await records.get("study_lessons", id);
    if (!lesson || lesson.status !== "Writing" || !lesson.material) continue;
    const { text, questions } = parseLesson(lesson.material);
    for (const old of await records.list("study_questions", { where: "=lesson == params.lesson", params: { lesson: id }, limit: 20 })) {
      await records.markObsolete("study_questions", old.id);
    }
    for (let index = 0; index < questions.length; index += 1) {
      const entry = questions[index];
      await records.create("study_questions", {
        lesson: id,
        position: index + 1,
        question: entry.question.slice(0, 1000),
        choice_a: entry.choices.A.slice(0, 500),
        choice_b: entry.choices.B.slice(0, 500),
        choice_c: entry.choices.C.slice(0, 500),
        choice_d: entry.choices.D.slice(0, 500),
        answer: entry.answer,
        why: entry.why.slice(0, 1000)
      });
    }
    // Written again, it starts fresh for everyone: each person's progress in it is put away (kept, not counted).
    for (const row of await records.list("study_progress", { where: "=lesson == params.lesson", params: { lesson: id }, limit: 100 })) {
      await records.markObsolete("study_progress", row.id);
    }
    await records.update("study_lessons", id, { text: text || lesson.material, status: "New", request: "" });
    if (!courses.includes(lesson.course)) courses.push(lesson.course);
    written += 1;
  }
  const ready = [];
  for (const course of courses) {
    const waiting = await records.list("study_lessons", { where: "=course == params.course && status == \"Writing\"", params: { course }, limit: 1 });
    if (waiting.length) continue;
    const row = await records.get("study_courses", course);
    if (row && row.status === "Writing") {
      await records.update("study_courses", course, { status: "Ready" });
      // Its learner hears it in their own chat with the app's bot, and can ask about it there (D-147).
      if (row.learner) await chat.tell(row.learner, "Your course \"" + (row.title || row.goal) + "\" is ready: every lesson is written. Open it whenever you like! 🎉");
      ready.push(course);
    }
  }
  return { written, ready };
}

// Lessons someone put away: everyone's progress in them is put away with them (each person's own, which only a job
// reaches for everyone), then the lessons. Kept, never deleted.
async function main(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  let progress = 0;
  for (const id of ids.slice(0, 20)) {
    const lesson = await records.get("study_lessons", id);
    if (!lesson || lesson.status !== "Put away") continue;
    for (const row of await records.list("study_progress", { where: "=lesson == params.lesson", params: { lesson: id }, limit: 100 })) {
      await records.markObsolete("study_progress", row.id);
      progress += 1;
    }
    await records.markObsolete("study_lessons", id);
  }
  return { progress };
}

// Roughly how long the lessons still being written will take: as long each as the written ones took so far, in
// minutes, rounded up; nothing to say before the first one is written.
function main(started, done, waiting, now) {
  const seconds = (Date.parse(now) - Date.parse(started)) / 1000;
  if (!(seconds > 0) || !(done > 0) || !(waiting > 0)) return "";
  const minutes = Math.ceil(((seconds / done) * waiting) / 60);
  return minutes <= 1 ? "⏱️ About a minute left" : "⏱️ About " + minutes + " minutes left";
}

// The person's answer to a question: kept in their own progress for its lesson (made the first time they answer one of
// its questions), once a question; whether it's right is worked out here. Answers and progress are each person's own.
async function main(input) {
  const question = await records.get("study_questions", String(input.question));
  if (!question) return { notify: "That question is no longer there." };
  const pick = String(input.pick || "");
  const [had] = await records.list("study_answers", { where: "=question == params.question", params: { question: question.id }, limit: 1 });
  if (had) return {};
  let [progress] = await records.list("study_progress", { where: "=lesson == params.lesson", params: { lesson: question.lesson }, limit: 1 });
  if (!progress) {
    const lesson = await records.get("study_lessons", question.lesson);
    progress = await records.create("study_progress", { course: lesson.course, lesson: question.lesson, done: false });
  }
  await records.create("study_answers", { progress: progress.id, question: question.id, picked: pick, correct: pick === question.answer });
  return {};
}

// The person's lesson done, with a celebration of their own score, and back to the lesson.
async function main(input) {
  const lessonId = String(input.lesson);
  const lesson = await records.get("study_lessons", lessonId);
  if (!lesson) return { notify: "That lesson is no longer there." };
  let [progress] = await records.list("study_progress", { where: "=lesson == params.lesson", params: { lesson: lessonId }, limit: 1 });
  if (!progress) progress = await records.create("study_progress", { course: lesson.course, lesson: lessonId, done: false });
  await records.update("study_progress", progress.id, { done: true, finished: String(input.today || "") || null });
  const total = Number(lesson.questions || 0);
  const right = Number(progress.stars || 0);
  return {
    celebrate: total ? "Lesson done! " + right + " of " + total + " right ⭐" : "Lesson done! 🌟",
    go: { screen: "lesson", params: { id: lessonId } }
  };
}

// Where the person goes next: a course's first lesson they haven't done, or a lesson's first question they haven't
// answered (the lesson itself once they've answered every one). Their progress and answers are their own.
async function main(input) {
  if (input.course) {
    const course = String(input.course);
    const lessons = await records.list("study_lessons", { where: "=course == params.course && status != \"Writing\" && status != \"Put away\"", params: { course }, sort: "position", limit: 100 });
    const done = new Set((await records.list("study_progress", { where: "=course == params.course && done == true", params: { course }, limit: 100 })).map((row) => row.lesson));
    const lesson = lessons.find((row) => !done.has(row.id));
    return lesson ? { go: { screen: "lesson", params: { id: lesson.id } } } : { notify: "You've done every lesson! 🏆" };
  }
  const lesson = String(input.lesson);
  const questions = await records.list("study_questions", { where: "=lesson == params.lesson", params: { lesson }, sort: "position", limit: 20 });
  const [progress] = await records.list("study_progress", { where: "=lesson == params.lesson", params: { lesson }, limit: 1 });
  const answered = new Set(progress ? (await records.list("study_answers", { where: "=progress == params.progress", params: { progress: progress.id }, limit: 40 })).map((row) => row.question) : []);
  const question = questions.find((row) => !answered.has(row.id));
  return question ? { go: { screen: "quiz", params: { lesson, id: question.id } } } : { go: { screen: "lesson", params: { id: lesson } } };
}

// The person's quiz of a lesson again: their answers to it put away (kept, not counted), from its first question.
async function main(input) {
  const lesson = String(input.lesson);
  const questions = await records.list("study_questions", { where: "=lesson == params.lesson", params: { lesson }, sort: "position", limit: 20 });
  if (!questions.length) return { notify: "This lesson has no quiz yet." };
  const [progress] = await records.list("study_progress", { where: "=lesson == params.lesson", params: { lesson }, limit: 1 });
  if (progress) {
    for (const answer of await records.list("study_answers", { where: "=progress == params.progress", params: { progress: progress.id }, limit: 40 })) {
      await records.markObsolete("study_answers", answer.id);
    }
  }
  return { go: { screen: "quiz", params: { lesson, id: questions[0].id } } };
}

// A unit or a lesson one place earlier (by -1) or later (by 1): it swaps places with its neighbour; a unit's lessons
// move with it, so the course's order stays the units' order.
async function main(input) {
  const table = input.table === "units" ? "study_units" : "study_lessons";
  const row = await records.get(table, String(input.id));
  if (!row) return { notify: "That's no longer there." };
  const where = table === "study_units" ? "=course == params.of" : "=unit == params.of";
  const siblings = await records.list(table, { where, params: { of: table === "study_units" ? row.course : row.unit }, sort: "position", limit: 100 });
  const index = siblings.findIndex((entry) => entry.id === row.id);
  const other = siblings[index + (Number(input.by) < 0 ? -1 : 1)];
  if (!other) return { notify: Number(input.by) < 0 ? "It's first already." : "It's last already." };
  await records.update(table, row.id, { position: other.position });
  await records.update(table, other.id, { position: row.position });
  if (table === "study_units") {
    for (const [unit, position] of [[row, other.position], [other, row.position]]) {
      const lessons = await records.list("study_lessons", { where: "=unit == params.unit", params: { unit: unit.id }, sort: "position", limit: 20 });
      for (let step = 0; step < lessons.length; step += 1) await records.update("study_lessons", lessons[step].id, { position: position * 100 + step + 1 });
    }
  }
  return {};
}

// A unit put away: its lessons are marked to be put away (put_away_lessons puts away everyone's progress with them), and
// the unit is put away now. Nothing is lost for good.
async function main(input) {
  const unit = await records.get("study_units", String(input.id));
  if (!unit) return { notify: "That unit is no longer there." };
  const lessons = await records.list("study_lessons", { where: "=unit == params.unit && status != \"Put away\"", params: { unit: unit.id }, limit: 40 });
  for (const lesson of lessons) await records.update("study_lessons", lesson.id, { status: "Put away" });
  await records.markObsolete("study_units", unit.id);
  return { notify: "Put away " + unit.title + " and its " + lessons.length + " lesson" + (lessons.length === 1 ? "" : "s") + ".", go: { screen: "course", params: { id: unit.course } } };
}

// A book someone put away: its contents (its parts) are put away, then the book, all marked obsolete so nothing is
// lost for good. Courses made from it stay as they are.
async function main(input) {
  const ids = [];
  for (const change of (input && input.changes) || []) {
    const id = String((change.record && change.record.id) || "");
    if (id && !ids.includes(id)) ids.push(id);
  }
  let parts = 0;
  for (const id of ids.slice(0, 2)) {
    const book = await records.get("books", id);
    if (!book || book.contents_status !== "Put away") continue;
    for (const part of await records.list("book_parts", { where: "=book == params.book", params: { book: id }, limit: 100 })) {
      await records.markObsolete("book_parts", part.id);
      parts += 1;
    }
    await records.markObsolete("books", id);
  }
  return { parts };
}

